import { expect, expectStatus, test } from "../../fixtures";

test.describe("vendor list paging", () => {
  test("a page past the last vendor is empty but still reports the total", { tag: "@LIF-15" }, async ({ apiAs, factory }) => {
    // Arrange
    const member = await apiAs("member");
    await factory.vendor({ as: "member" });
    const firstPage = await expectStatus<{ items: unknown[]; total: number }>(
      await member.get("/api/vendors", { params: { limit: 10, offset: 0 } }),
      200,
    );
    const offset = firstPage.total + 100;

    // Act
    const response = await member.get("/api/vendors", { params: { limit: 10, offset } });

    // Assert
    const body = await expectStatus<{ items: unknown[]; total: number }>(response, 200);
    expect(body.items).toEqual([]);
    expect(body.total).toBe(firstPage.total);
  });
});
